<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('GET');$user=require_permission('MOVIMIENTO_VER');$id=(int)($_GET['id']??0);if($id<=0)json_response(['ok'=>false,'error'=>'Archivo inválido'],400);$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);$st=$db->prepare("SELECT a.*,pm.tipo,pm.departamento_id,pm.solicitado_por_usuario_id,pm.otorgado_a_usuario_id,pm.registrado_por_usuario_id FROM presupuesto_movimiento_archivo a JOIN presupuesto_movimiento pm ON pm.movimiento_id=a.movimiento_id WHERE a.archivo_id=? LIMIT 1");$st->bind_param('i',$id);$st->execute();$row=$st->get_result()->fetch_assoc();$st->close();if(!$row||!movement_is_visible($db,$user,$row)){$db->close();http_response_code(404);exit('Archivo no encontrado');}$db->close();$path=project_root().'/'.$row['ruta_relativa'];if(!is_file($path)){http_response_code(404);exit('Archivo no encontrado');}header('Content-Type: '.$row['mime_type']);header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.rawurlencode($row['nombre_original']).'"');header('X-Content-Type-Options: nosniff');readfile($path);exit;
